import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const root=path.resolve(import.meta.dirname,'..'), base=path.join(root,'data/result-completion-projects'), out=path.join(root,'outputs/v3-double-scene');const hash=async f=>{const h=createHash('sha256');h.update(await fs.readFile(f));return h.digest('hex')};
const files=await fs.readdir(base).catch(()=>[]);const cases=[];for(const id of files.filter(x=>/^[\w-]+$/.test(x))){const p=path.join(base,id,'native-project.json');let project;try{project=JSON.parse(await fs.readFile(p));}catch{continue}if(project.request?.pipelineVersion!==3)continue;for(const job of project.jobs||[]){const dir=path.join(base,id,'versions',job.id);if(!(await fs.stat(dir).catch(()=>null))||!job.runId)continue;const audit=path.join(out,'cases',id+'-'+job.id,'audit-bundle');await fs.mkdir(audit,{recursive:true});const input={projectId:id,jobId:job.id,runId:job.runId,agentGenerated:true,materialRoot:project.request?.materialRoot||null,scene:project.request?.businessContract?.scenarioId,request:project.request?.message};await fs.writeFile(path.join(audit,'input.json'),JSON.stringify(input,null,2));for(const n of ['business-contract.json','production-admission.json','material-analysis.json','action-timeline.json','creative-direction.json','story-plan.json','source-selections.json','hyperframes-resources.json','resource-receipts.json','document.json','preview-review.json','repair-log.json','media-review.json','final-quality-report.json','human-review.json','formal-delivery.json','status.json','run-summary.json']){const src=path.join(dir,n);if(await fs.stat(src).catch(()=>null))await fs.copyFile(src,path.join(audit,n));}const video=path.join(dir,'commerce-final.mp4');if(await fs.stat(video).catch(()=>null)){await fs.copyFile(video,path.join(audit,'final.mp4'));await fs.writeFile(path.join(audit,'final.sha256'),await hash(video));}const summary={...input,status:job.status,stage:job.stage,error:job.error,quality:job.quality,revisionId:job.revisionId||null,artifactDirectory:audit,formalDelivery:'not_claimed'};await fs.writeFile(path.join(audit,'run-summary.json'),JSON.stringify(summary,null,2));cases.push(summary);}}
await fs.writeFile(path.join(out,'cases.json'),JSON.stringify({generatedAt:new Date().toISOString(),cases},null,2));console.log(JSON.stringify({cases:cases.length,statuses:cases.map(c=>c.status)}));
